typedef const class stringx* vm_str_t;

class stringx
{
public:
  enum fmt_t { fmt };
  stringx(fmt_t, const char*, ...);
  stringx& operator=(const stringx&);
};

class vm_stack
{
public:
  char* SP;
  void pop(int n) { SP -= n; }
  char* get_SP() const { return SP; }
  bool push(const char*, int);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual ~function();
    virtual bool operator()(vm_stack&, entry_t);
  };
};

class vector3d
{
public:
  float x, y, z;
};

extern stringx script_strings[];
extern int script_strings_cnt;

#define MAX_STATIC_TO_STR_STRINGS 16
#define SLF_PARMS stack.pop(sizeof(parms_t)); parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN stack.push((char*)&result, sizeof(result))
#define SLF_DONE return true

class slf_to_str_vector3d_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d v;
  };

  virtual bool operator ()(vm_stack &stack, entry_t entry);
};

bool slf_to_str_vector3d_t::operator ()(vm_stack &stack, entry_t entry)
{
  SLF_PARMS;

  script_strings[script_strings_cnt] = stringx(stringx::fmt, "<%.3f, %.3f, %.3f>", parms->v.x, parms->v.y, parms->v.z);
  vm_str_t result = &script_strings[script_strings_cnt];
  ++script_strings_cnt;
  if(script_strings_cnt >= MAX_STATIC_TO_STR_STRINGS)
    script_strings_cnt = 0;

  SLF_RETURN;
  SLF_DONE;
}
